(99, '【雕牌】无磷洗衣粉1.28kg', '', 'https://xcx.szhxch.com/i/1705741116.jpg', '[]', '1*1.28kg', '包', 65, '清洁用品', 11.00, 8.60, 11.00, 9.78, 9.56, 0.00, '[{\"a\":0,\"b\":0},{\"a\":0,\"b\":0},{\"a\":0,\"b\":0}]', '2024-03-26 17:19:59', 'CF038', 0, '', 0, 1001, NULL, '关'),
(100, '84消毒液', '', 'https://xcx.szhxch.com/i/1705741192.jpg', '[]', '1*20kg', '桶', 3, '清洁用品', 59.00, 38.00, 59.00, 54.29, 48.72, 0.00, '[{\"a\":0,\"b\":0},{\"a\":0,\"b\":0},{\"a\":0,\"b\":0}]', '2024-03-26 17:18:06', 'W0008', 0, '<p>84消毒液，适用家庭，宾馆，医院，饭店及其它公共场所的物体表面消毒。</p><p>适用方法：1、兑水比例1:29，餐饮具除菌，浸泡15分钟用无菌水冲洗干净；织物除菌，浸泡10分钟后用无菌水冲洗干净。</p><p>2、兑水比例1:29，厕所坐厕消毒，倒入坐厕中10分钟后过水。</p><p>3、兑水1:99，厨房瓷盆、浴缸等，将兑好水倒入瓷盆清洗后过水。</p><p>重量：20公斤/1桶</p>', 0, 1001, NULL, '关'),
(103, '（抽压器）洗洁精吸取器 ', '', 'https://xcx.szhxch.com/i/1705742613.jpg', '[]', '1支', '支', 109, '其它', 9.00, 5.40, 9.00, 7.15, 5.89, 0.00, '[{\"a\":0,\"b\":0},{\"a\":0,\"b\":0},{\"a\":0,\"b\":0}]', '2024-03-26 17:39:30', 'G0055', 0, '<p>洗洁精吸取器&nbsp; ，入桶长度：约37cm，总长约48cm，拉开长约85cm。适用于一般洗洁精、漂白水、洗手液20kg装桶</p><p>数量：1支</p><p><br/></p>', 0, 1001, NULL, '关'),
